export const FUENTES: string[] = [
  /* contracts/assets/dinero.js */
  "/* Leer un importe de dinero \u2014 UNA sola forma para toda la suite. 17-ago-2026\n   ============================================================================\n   POR QUE EXISTE. Habia DOS implementaciones de esto, una en `contracts/app.html`\n   y otra en `facturas/totales.js`, y no coincidian. Medido antes de unificarlas,\n   discrepaban en seis casos y ninguna era mejor que la otra: cada una acertaba\n   justo donde la otra fallaba.\n\n     entrada      Contratos   Facturas   quien acertaba\n     -5.000       +5000       -5000      Facturas \u2014 Contratos se comia el signo\n     \"\"           null        0          las dos, en su contexto (ver abajo)\n     1.2345       1.2345      12345      Contratos \u2014 un tipo de cambio lleva\n                                         cuatro decimales, no son miles\n     12.34.56     123456      1234.56    Contratos \u2014 dos separadores son miles\n     1,2,3        123         12.3       Contratos\n\n   Un mismo importe leido con distinto SIGNO segun que herramienta lo tocara, en\n   un ERP que mueve mas de 100 M\u20ac. Es la misma familia de fallo que costo una\n   semana de cobros dobles en B2K: el mismo dato en dos sitios que se separan.\n\n   ESTA FUNCION ES LA SUMA DE LAS DOS, no una tercera version: se conserva la\n   regla de separadores de Contratos y el tratamiento del signo de Facturas.\n\n   QUE DEVUELVE CUANDO NO HAY NUMERO. `null`, y no 0. La diferencia importa: un\n   contrato SIN precio no es un contrato de 0 \u20ac, y guardarlo como 0 lo mete en\n   las sumas de Operaciones y en el calculo de lo cobrado. Donde 0 sea la\n   respuesta correcta \u2014una linea de factura vacia no suma\u2014 el que llama escribe\n   `?? 0`, que es explicito y se lee. */\n\n/* Reglas del separador, con el caso que justifica cada una:\n   \u00b7 el ULTIMO separador es el decimal \u2026 \"1.500,50\" \u2192 1500.5\n   \u00b7 salvo que aparezca mas de una vez \u2026 \"1.000.000\" y \"12.34.56\" son miles\n   \u00b7 salvo que le sigan EXACTAMENTE 3 cifras \u2026 \"79.000\" y \"1,500\" son miles\n   ponytail asumido: \"79.500\" queriendo decir 79 con 5 decimas se lee 79500. En\n   estos contratos no se escribe asi, y romper \"79.500\" = 79.500 \u20ac seria peor. */\nfunction lwParseImporte(v){\n  const bruto = String(v == null ? '' : v);\n  // El signo se mira ANTES de limpiar: `[^\\d.,]` se lo llevaba por delante y\n  // por eso Contratos convertia -5.000 en +5000.\n  const negativo = /-/.test(bruto.trim().charAt(0)) || /^\\s*-/.test(bruto);\n  const s = bruto.replace(/[^\\d.,]/g, '');\n  if(!/\\d/.test(s)) return null;\n  const d = s.lastIndexOf('.'), c = s.lastIndexOf(',');\n  let sep = d > c ? '.' : (c > d ? ',' : '');\n  const resto = s.slice(s.lastIndexOf(sep) + 1);\n  if(sep && (s.split(sep).length > 2 || /^\\d{3}$/.test(resto))) sep = '';\n  const n = parseFloat(sep ? s.replace(/[.,]/g, m => m === sep ? '.' : '')\n                           : s.replace(/[.,]/g, ''));\n  if(!isFinite(n)) return null;\n  return negativo ? -n : n;\n}\n\n/* ============================================================================\n   ESCRIBIR UN IMPORTE \u2014 la otra mitad, 17-ago-2026 (auditor\u00eda)\n   ============================================================================\n   Este fichero naci\u00f3 esta misma semana para que hubiera UNA forma de LEER un\n   importe, despu\u00e9s de medir seis discrepancias entre Contratos y Facturas. La\n   mitad sim\u00e9trica \u2014imprimirlo\u2014 se qued\u00f3 fuera, y para cuando se audit\u00f3 ya hab\u00eda\n   cuatro implementaciones vivas que tampoco coincid\u00edan. Medido ejecut\u00e1ndolas:\n\n     valor          Facturas \u00b7 Operaciones   Compradores \u00b7 Panel\n     1234.5         1.234,50 \u20ac               1234,5 \u20ac\n     164000         164.000,00 \u20ac             164.000 \u20ac\n     1234567.891    1.234.567,89 \u20ac           1.234.567,891 \u20ac\n\n   El mismo importe con tres decimales en una pantalla y dos en otra. Y peor que\n   la est\u00e9tica: `toLocaleString('es')` no recibe la moneda, as\u00ed que un importe en\n   rupias sale con decimales que en rupias NO EXISTEN \u2014 la rupia no tiene\n   c\u00e9ntimos, y por eso `DECIMALES` existe desde el primer d\u00eda en las facturas.\n\n   La implementaci\u00f3n es la de `facturas/totales.js`, que era la \u00fanica de las\n   cuatro que conoc\u00eda la moneda. No es una quinta versi\u00f3n: es esa, mudada aqu\u00ed,\n   con `totales.js` delegando igual que ya delega `parseImporte`.\n\n   `de-DE` y no `es-ES`: los dos dan \u00ab1.234.567,89\u00bb, pero el alem\u00e1n agrupa de\n   tres en tres tambi\u00e9n en los n\u00fameros de cuatro cifras (\u00ab1.500\u00bb) y el espa\u00f1ol\n   los deja pegados (\u00ab1500\u00bb). En una columna de importes eso es una fila que no\n   alinea con las dem\u00e1s.\n   ========================================================================== */\n\n/* Decimales por moneda. La rupia no usa c\u00e9ntimos. Si aparece una moneda nueva,\n   se a\u00f1ade AQU\u00cd y no en la herramienta que la necesite primero. */\nconst LW_DECIMALES = { EUR:2, USD:2, AUD:2, IDR:0 };\n\n/* Importe a texto para ense\u00f1arlo. Devuelve SIEMPRE con su moneda detr\u00e1s: un\n   n\u00famero suelto en esta suite no significa nada, porque se opera en cuatro. */\nfunction lwFormatoImporte(n, moneda){\n  const d = LW_DECIMALES[moneda] != null ? LW_DECIMALES[moneda] : 2;\n  return new Intl.NumberFormat('de-DE', { minimumFractionDigits:d, maximumFractionDigits:d })\n    .format(Number(n) || 0) + (moneda ? ' ' + moneda : '');\n}\n\n/* Node lo necesita para el test; el navegador lo ignora. Sin `module.exports`\n   las constantes quedan globales, que es como las usan las nueve herramientas. */\nif(typeof module !== 'undefined' && module.exports)\n  module.exports = { lwParseImporte, lwFormatoImporte, LW_DECIMALES };\n",
  /* contracts/assets/entities.js */
  "/* ============================================================================\n   Identidad de Lawang (y el cargador de las cuentas de cobro) \u2014 FUENTE \u00daNICA\n   ----------------------------------------------------------------------------\n   Lo usan `contracts/app.html` (contratos) y `facturas/index.html` (facturas).\n   Viv\u00eda inline en app.html hasta el 27-jul-2026; se saca aqu\u00ed porque un n\u00famero\n   de cuenta duplicado en dos herramientas se corrige en una y se queda viejo en\n   la otra \u2014 y ah\u00ed el fallo es dinero enviado al sitio equivocado.\n\n   Define tres globales: CUENTAS_BANCARIAS, SOCIEDADES y APODERADOS_HAK_SEWA.\n   Sin m\u00f3dulos a prop\u00f3sito: las dos apps son HTML plano con <script> cl\u00e1sico.\n\n   Los textos que llevan palabras van como {es,en,id} porque los contratos se\n   imprimen en tres idiomas; las facturas usan solo `es`/`en`.\n   ========================================================================== */\n\n/* ---------- cuentas de cobro \u2014 YA NO VIVEN AQU\u00cd (6-ago-2026) ----------\n   Los 15 n\u00fameros de cuenta estaban escritos en este fichero, y este fichero es\n   P\u00daBLICO por dos caminos a la vez: se sirve con 200 sin login (lo cargan las\n   nueve herramientas de la suite y el portal del comprador) y est\u00e1 en el repo\n   `jvrcervantes-oss/lawang`, que es p\u00fablico, legible en crudo desde el 27-jul.\n   Unas coordenadas bancarias abiertas son la materia prima de un fraude de\n   transferencia, y a diferencia de una contrase\u00f1a **un n\u00famero de cuenta no se\n   rota**: la \u00fanica salida es que dejen de publicarse.\n\n   Ahora viven en la tabla `public.cuentas_bancarias` con RLS: SELECT solo para\n   `authenticated`, ni lectura ni escritura para `anon` (verificado con un GET\n   an\u00f3nimo al REST: 401, no un `[]` ambiguo). El repo se queda p\u00fablico a\n   prop\u00f3sito \u2014 de \u00e9l depende el auto-deploy de Hostinger; lo que sale del repo\n   son las cuentas, no el hosting.\n\n   SOCIEDADES se queda: es la identidad que ya va impresa en todo contrato y\n   factura que el comprador tiene en la mano, as\u00ed que ocultarla no protege nada.\n\n   C\u00f3mo se usa: `await cargarCuentasBancarias(sb)` una vez al arrancar, antes de\n   pintar el select de cuentas o de imprimir un documento. Quien lea\n   CUENTAS_BANCARIAS despu\u00e9s lo hace igual que siempre. */\nconst CUENTAS_BANCARIAS = {};\nlet CUENTAS_PROMESA = null;\n\n/* Rellena el objeto EN SU SITIO (Object.assign, nunca reasignar): `firma-submit`\n   y `facturas/documento.test.js` publican esta misma referencia en su `caja`\n   evaluando los cuatro ficheros compartidos de una vez, as\u00ed que cambiar el\n   objeto por otro los dejar\u00eda leyendo uno vac\u00edo para siempre.\n   Si la consulta falla, LANZA y deja la promesa a null para poder reintentar: un\n   fallo silencioso aqu\u00ed imprime un contrato sin datos de pago, que es\n   exactamente el error que este fichero existe para evitar. */\nfunction cargarCuentasBancarias(sb){\n  if(CUENTAS_PROMESA) return CUENTAS_PROMESA;\n  CUENTAS_PROMESA = (async () => {\n    const { data, error } = await sb.from('cuentas_bancarias')\n      .select('clave,label,titular,banco,cuenta,codigo,direccion,extra')\n      .eq('activa', true).order('orden');\n    if(error){ CUENTAS_PROMESA = null; throw error; }\n    (data || []).forEach(r => {\n      CUENTAS_BANCARIAS[r.clave] = { label:r.label, titular:r.titular, banco:r.banco,\n        cuenta:r.cuenta, codigo:r.codigo, direccion:r.direccion, extra:r.extra };\n    });\n    return CUENTAS_BANCARIAS;\n  })();\n  return CUENTAS_PROMESA;\n}\n\n/* ---------- apoderados de la serie Hak Sewa \u2014 MISMO MOTIVO que las cuentas ----------\n   El NIK (identificador nacional indonesio) y la direcci\u00f3n de un apoderado son\n   datos personales de un PARTICULAR, no de una sociedad \u2014 a diferencia del\n   representante de SOCIEDADES (nombre+pasaporte, ya p\u00fablico por registro\n   mercantil), esto no tiene ese mismo colch\u00f3n. Viv\u00edan en tokens.json, que se\n   sirve igual de p\u00fablico que este fichero (hallazgo Seguridad, 12-ago-2026).\n   Ahora en `public.apoderados_hak_sewa` con la misma RLS que cuentas_bancarias\n   (SELECT solo `authenticated`). tokens.json se queda solo con los NOMBRES\n   (las opciones del <select>), que hacen falta para pintar el formulario. */\nconst APODERADOS_HAK_SEWA = {};\nlet APODERADOS_PROMESA = null;\nfunction cargarApoderadosHakSewa(sb){\n  if(APODERADOS_PROMESA) return APODERADOS_PROMESA;\n  APODERADOS_PROMESA = (async () => {\n    const { data, error } = await sb.from('apoderados_hak_sewa')\n      .select('clave,edad,ocupacion,direccion,nik,ktp')\n      .eq('activo', true).order('orden');\n    if(error){ APODERADOS_PROMESA = null; throw error; }\n    (data || []).forEach(r => {\n      APODERADOS_HAK_SEWA[r.clave] = { edad:r.edad, ocupacion:r.ocupacion,\n        direccion:r.direccion, nik:r.nik, ktp:r.ktp };\n    });\n    return APODERADOS_HAK_SEWA;\n  })();\n  return APODERADOS_PROMESA;\n}\n\n/* ---------- sociedades emisoras ----------\n   `razon`/`marca`/`domicilio`/`npwp`/`rep` alimentan tanto los marcadores\n   {{prom_*}} de las plantillas de contrato como la cabecera del emisor en las\n   facturas. `cred` (nacionalidad + documento del representante) solo la usan\n   los contratos.\n\n   Identidad del documento por sociedad (30-jul-2026) \u2014 cada sociedad emite con\n   su marca, no con la de Lawang, y una factura de PT SAN DAL WOODS con el logo\n   de Lawang dice que la emite otra empresa:\n     `logo`      cabecera del documento\n     `logoAlto`  alto del logo (por defecto 15mm)\n     `logo2`     segundo logo debajo del primero (el lockup de palabra), opcional\n     `logo2Ancho` ancho de ese segundo logo\n     `folio`     color del papel\n     `tinta`     {primary, deep} = todo lo coloreado del documento\n   Lo usan hoy las facturas (los contratos llevan su logo fijo en cada\n   plantilla). A\u00f1adir una sociedad = un bloque m\u00e1s aqu\u00ed, nada m\u00e1s. */\nconst SOCIEDADES = {\n  /* \u26a0\ufe0f La CLAVE es `tepi_sungai` y NO se toca: va guardada dentro de cada\n     contrato (`sociedad_firmante`) y de cada factura, y las plantillas la miran\n     en `<!--if:sociedad_firmante=tepi_sungai-->`. Renombrarla dejar\u00eda a los\n     contratos ya emitidos apuntando a una sociedad que no existe y sin logo.\n     Lo que se corrige el 31-jul-2026 es el nombre que se IMPRIME: la sociedad\n     est\u00e1 inscrita como \u00abPT TEPI SUN GAI\u00bb, separado, y lo emit\u00edamos junto. Es lo\n     mismo que reclamaba el memor\u00e1ndum del abogado del comprador sobre CR00003.\n     Ojo al leerlo: \u00abtepi sungai\u00bb junto es riverbank en indonesio y es el nombre\n     de la colecci\u00f3n en la web p\u00fablica \u2014 ese s\u00ed va junto y no hay que tocarlo. */\n  tepi_sungai: {\n    label: 'PT Tepi Sun Gai (marca \u00abLawang Tropical Properties\u00bb)',\n    razon: 'PT TEPI SUN GAI', marca: 'LAWANG TROPICAL PROPERTIES',\n    logo: '/contracts/assets/brand/lawang-logo-v3-dark.png',\n    /* Este lockup es una tira de 7,2:1: al lado del emisor no cabe grande sin\n       dejarle una columna de 52mm en la que el domicilio se parte en nueve\n       l\u00edneas. Decisi\u00f3n del owner (30-jul, 17:10h): aqu\u00ed el logo va GRANDE y el\n       emisor DEBAJO, que es lo que aprovecha el ancho de una tira. San Dal\n       Woods, cuyo lockup es 2,1:1, se queda con el emisor al lado. */\n    logoAlto: '14mm',            // 14mm \u00d7 7,2:1 = 100,7mm de ancho\n    emisorDebajo: true,\n    // verde claro: el equivalente en la gama de marca al crema de SAN DAL WOODS.\n    // Historia del ajuste (30-jul, owner): #F3F7F0 \u2192 #DAE6D0 (-10% de\n    // luminosidad) se pas\u00f3 de fuerte, as\u00ed que se queda a MEDIO camino, en -5%.\n    // El crema de San Dal Woods s\u00ed se queda con el -10%: el verde carga m\u00e1s a\n    // la vista que el crema al mismo nivel de luminosidad.\n    folio: '#E6EFE0',\n    domicilio: 'Jalan Gunung Tangkuban Perahu, Gg. Dewi Sri Dusun Tegal Buah RT. 000 RW. 000, Padangsambian Kelod, Denpasar Barat, Kota Denpasar, Bali 80117 Indonesia',\n    npwp: '1000.0000.0619.8026',\n    /* \u26a0\ufe0f EL REPRESENTANTE DE ESTA SOCIEDAD ES I WAYAN EKA ARYAWAN (desde\n       11-ago-2026, petici\u00f3n del owner \u2014 sustituye a I Made Monjong Adhi\n       Nugruah). Identificaci\u00f3n (NIK) tomada del mismo cat\u00e1logo que ya usa el\n       apoderado de la serie Hak Sewa (hoy `APODERADOS_HAK_SEWA`, arriba en\n       este mismo fichero \u2014 viv\u00eda en tokens.json cuando se escribi\u00f3 esta nota).\n       El 4-ago-2026 cambi\u00e9 este campo a Pablo Cantero Gamb\u00edn leyendo mal al\n       owner: dijo \u00aben este caso mete a Pablo Cantero\u00bb refiri\u00e9ndose SOLO al\n       PPJB de Bonian C2, y lo apliqu\u00e9 aqu\u00ed, que es la ficha de la que beben\n       las NUEVE plantillas. Revertido el mismo d\u00eda.\n       Si alg\u00fan documento concreto lo firma otra persona, va escrito EN ESE\n       documento \u2014como est\u00e1 hoy en `templates/ppjb_bonian_c2.html`\u2014, no aqu\u00ed. */\n    rep: 'I Wayan Eka Aryawan',\n    // NIB y NPWP personal del firmante: los pide el PPJB de Bonian Beach en sus\n    // antecedentes. Van aqu\u00ed y no en la plantilla porque son identidad de la\n    // sociedad, y la identidad tiene una sola fuente (este fichero). Opcionales:\n    // la plantilla los envuelve en <!--opt:--> y la frase se cierra sola si una\n    // sociedad no los tiene, en vez de imprimir el marcador.\n    // \u26a0\ufe0f `rep_npwp` es el del representante que figura ARRIBA en `rep`. Si se\n    // cambia uno hay que cambiar el otro: son la misma persona.\n    // `rep_npwp` va VAC\u00cdO: el NPWP 53.045.376.0-905.000 que trae el PPJB de\n    // Bonian es el de Pablo Cantero, y aqu\u00ed el representante es I Wayan Eka\n    // Aryawan. Poner uno con el nombre del otro es peor que no poner ninguno\n    // \u2014 la frase se cierra sola gracias al <!--opt:-->.\n    nib: '2410250046282', rep_npwp: '',\n    cred: { es: 'de nacionalidad Indonesia, con documento de identidad indonesio ID 5102010606870001',\n            en: 'Indonesian nationality, holder of Indonesian identity document ID 5102010606870001',\n            id: 'berkewarganegaraan Indonesia, dengan dokumen identitas Indonesia ID 5102010606870001' } },\n  san_dal_woods: {\n    label: 'PT SAN DAL WOODS',\n    razon: 'PT SAN DAL WOODS', marca: '',\n    /* Lockup \u00fanico: el owner junt\u00f3 isotipo y palabra en una sola imagen\n       (`swnewlogo.png`, 30-jul 15:40h). Se sirve una copia con el FONDO QUITADO:\n       el original viene con el crema viejo (#F8F7F2) opaco, que sobre el folio\n       actual (#E7E3D2) se ve\u00eda como un rect\u00e1ngulo m\u00e1s claro pegado encima; el\n       multiply tampoco lo salva, porque ese crema no es blanco y ti\u00f1e.\n       La copia va adem\u00e1s RECORTADA a la tinta (el original tra\u00eda 20px de aire\n       por lado): as\u00ed el alto que se pide aqu\u00ed es el alto que se ve, y el logo se\n       puede alinear con el t\u00edtulo del documento sin adivinar el margen interno.\n       479\u00d7227 px (ratio 2,11): a 24mm de alto son 50,6mm de ancho, lo que cabe\n       al lado de los datos del emisor. Subirlo es una l\u00ednea, pero cada mm de\n       alto se lo come el presupuesto de UNA p\u00e1gina (facturas/index.html). */\n    logo: '/contracts/assets/brand/sandalwoods-lockup.png',\n    logoAlto: '24mm',\n    folio: '#E7E3D2',              // crema, +10% de fuerza sobre el #f8f7f2 inicial (-10% de luminosidad)\n    // Tinta del documento cuando emite esta sociedad. `primary` es el marr\u00f3n\n    // exacto del SWlogo (muestreado del PNG: #662906) y `deep` el Burnt Earth\n    // de la gu\u00eda de marca, m\u00e1s oscuro, para los titulares. Sin `tinta` el\n    // documento se queda con el verde/lagoon de Lawang (brand.css).\n    tinta: { primary:'#662906', deep:'#42210B' },\n    domicilio: 'Jl. Sunset Road No. 89, Pertokoan Sunset Indah I, No. 3B RT. 000 RW. 000, Kuta, Kuta, Kab. Badung, Bali',\n    npwp: '1000.0000.0012.5018', rep: 'Pablo Cantero Gamb\u00edn',\n    cred: { es: 'de nacionalidad espa\u00f1ola, con pasaporte espa\u00f1ol n\u00ba PAL648254',\n            en: 'Spanish nationality, holder of Spanish passport no. PAL648254',\n            id: 'berkewarganegaraan Spanyol, dengan paspor Spanyol no. PAL648254' } },\n  /* SANDAL WOODS Ltd (Hong Kong) \u2014 a\u00f1adida 12-ago-2026, petici\u00f3n del owner.\n     Misma marca comercial SandalWoods que `san_dal_woods` (PT indonesia),\n     veh\u00edculo legal distinto: se reutiliza el mismo lockup/tinta/folio por\n     continuidad visual de marca; cambiar aqu\u00ed si el cliente quiere un logo\n     propio para esta sociedad.\n     `npwpLabel`: Hong Kong no tiene NPWP (impuesto indonesio) \u2014 su\n     identificaci\u00f3n fiscal es el CRN (Company Registration Number). Sin este\n     campo, facturas/documento.js imprim\u00eda \"NPWP 79887714\", una etiqueta\n     falsa; con \u00e9l, cada sociedad imprime la suya (las dos PT se quedan con\n     el 'NPWP' de siempre, por defecto en documento.js).\n     `rep`/`cred`: representante Pablo Cantero Gamb\u00edn (12-ago, confirmado por\n     el owner) \u2014 mismo pasaporte que ya tiene registrado como representante\n     de `san_dal_woods`, la PT hermana de la misma marca: es la misma persona\n     real, no un dato nuevo inventado.\n     \u26a0\ufe0f Pendiente sin resolver (owner/Legal, 12-ago): las 9 plantillas de\n     contrato declaran al Promotor \"sociedad de nacionalidad Indonesia\" / \"an\n     Indonesian company\" / \"perusahaan yang didirikan berdasarkan hukum\n     Indonesia\" \u2014 cierto para las dos PT, FALSO para esta Ltd de Hong Kong.\n     Con el representante ya puesto, esta sociedad S\u00cd aparece en el\n     desplegable \"Sociedad firmante\" de Contratos, pero elegirla en cualquiera\n     de las 9 plantillas imprime esa frase incorrecta hasta que se revise\n     plantilla por plantilla \u2014 el agente que la use para firmar un contrato\n     real (no solo facturar) tiene que corregir esa cl\u00e1usula a mano o avisar\n     antes de imprimir el documento final. */\n  sandal_woods_ltd: {\n    label: 'SANDAL WOODS Ltd (Hong Kong)',\n    razon: 'SANDAL WOODS Ltd', marca: '',\n    logo: '/contracts/assets/brand/sandalwoods-lockup.png',\n    logoAlto: '24mm',\n    folio: '#E7E3D2',\n    tinta: { primary:'#662906', deep:'#42210B' },\n    domicilio: \"Suite D, 6/F Ho Lee Comm Bldg, 38-44 D'Aguilar St, Central, Hong Kong\",\n    npwpLabel: 'CRN', npwp: '79887714',\n    rep: 'Pablo Cantero Gamb\u00edn', nib: '', rep_npwp: '',\n    cred: { es: 'de nacionalidad espa\u00f1ola, con pasaporte espa\u00f1ol n\u00ba PAL648254',\n            en: 'Spanish nationality, holder of Spanish passport no. PAL648254',\n            id: 'berkewarganegaraan Spanyol, dengan paspor Spanyol no. PAL648254' } },\n};\n\n/* ---------- credenciales de quien puede aparecer como \"Firmante\" ----------\n   El campo \"Firmante\" de Gesti\u00f3n del contrato (ver applyPromotor en app.html)\n   permite imprimir en un documento a alguien distinto del representante POR\n   DEFECTO de la sociedad elegida \u2014 hasta el 11-ago-2026 eso se resolv\u00eda\n   buscando `data.firmante` entre los `.rep` de SOCIEDADES, lo que funcionaba\n   mientras cada nombre siguiera siendo el rep actual de alguna sociedad.\n   Dej\u00f3 de valerse el 11-ago-2026: al cambiar tepi_sungai.rep de I Made Monjong\n   Adhi Nugruah a I Wayan Eka Aryawan, cuatro contratos ya creados pero sin\n   firmar (CC00020, CC00019, RP00031, CR00018) quedaron guardados con\n   firmante=I Made Monjong \u2014 al reabrirlos, la b\u00fasqueda ya no encontraba a\n   nadie con ese `.rep` y el documento imprim\u00eda en silencio al representante\n   NUEVO, sin que nadie lo hubiera elegido (hallazgo Legal, confirmado con los\n   cuatro n\u00fameros de contrato reales). Esta tabla desacopla \"qui\u00e9n puede\n   aparecer firmando\" de \"qui\u00e9n es HOY el rep por defecto de cada sociedad\":\n   a\u00f1adir aqu\u00ed = una entrada m\u00e1s, y NUNCA se borra la de alguien que ya pudo\n   firmar o puede tener un contrato en vuelo con su nombre guardado. */\nconst FIRMANTES_CRED = {\n  [SOCIEDADES.tepi_sungai.rep]: { rep_npwp: SOCIEDADES.tepi_sungai.rep_npwp, cred: SOCIEDADES.tepi_sungai.cred },\n  [SOCIEDADES.san_dal_woods.rep]: { rep_npwp: SOCIEDADES.san_dal_woods.rep_npwp, cred: SOCIEDADES.san_dal_woods.cred },\n  // retirado como rep por defecto el 11-ago-2026 \u2014 se queda aqu\u00ed SOLO para que\n  // los contratos ya creados con su nombre no cambien de comparecencia solos.\n  'I Made Monjong Adhi Nugruah': { rep_npwp: '', cred: {\n    es: 'de nacionalidad Indonesia, con documento de identidad indonesio ID 5171021704720002',\n    en: 'Indonesian nationality, holder of Indonesian identity document ID 5171021704720002',\n    id: 'berkewarganegaraan Indonesia, dengan dokumen identitas Indonesia ID 5171021704720002' } },\n};\n\n/* ---------- etiqueta humana de `contratos.tipo` ----------\n   Copiado a prop\u00f3sito, no movido: ya viv\u00eda inline en operaciones/index.html\n   (TIPO_ES) desde el 5-ago y ese sitio sigue funcionando \u2014 sacarlo de ah\u00ed para\n   esta tarea habr\u00eda sido tocar un fichero que nadie pidi\u00f3 cambiar. Esta copia\n   la usa `facturas/index.html` para el prefijo \"[Parcela]\"/\"[Construcci\u00f3n]\"\n   cuando combina conceptos de dos contratos vinculados (7-ago-2026). Si diverge\n   de la de operaciones, unificarlas aqu\u00ed ser\u00eda el momento \u2014 no antes. */\nconst TIPO_ES = { reserva_parcela:'Parcela', construccion:'Construcci\u00f3n', contrato_general:'Contrato General',\n  commercial_offer:'Oferta Comercial', carta_reserva:'Carta de Reserva',\n  carta_reserva_ampliada:'Carta de Reserva ampliada', acuerdo_comercial:'Acuerdo Comercial',\n  protocolo_operativo:'Protocolo Operativo', ppjb_bonian:'PPJB Bonian Beach',\n  poa:'POA (Poder Notarial)' };\n",
  /* facturas/totales.js */
  "/* Aritm\u00e9tica y formato de dinero de las facturas de Lawang.\n   Fuera del HTML para poder pasarle un test de verdad (totales.test.js).\n   Se carga con <script src> en index.html y con require() en node. */\n\n// Decimales por moneda: la rupia no usa c\u00e9ntimos.\nconst DECIMALES = { EUR:2, USD:2, AUD:2, IDR:0 };\n\n/* Importe tecleado a n\u00famero. El agente escribe indistintamente \"1.500,50\",\n   \"1,500.50\" o \"1500.5\": manda el \u00daLTIMO separador como decimal, y solo si\n   deja 1-2 d\u00edgitos detr\u00e1s (si no, es separador de miles: \"1.500\" = 1500). */\nfunction parseImporte(v){\n  /* La version buena vive en contracts/assets/dinero.js desde el 17-ago-2026.\n     Aqui se DELEGA, y `?? 0` conserva el contrato de esta funcion: una linea de\n     factura vacia suma 0, mientras que un contrato sin precio es `null` y no un\n     contrato de 0 \u20ac.\n\n     \u26a0\ufe0f EL RESPALDO DE ABAJO NO ES CODIGO MUERTO, pero desde el 17-ago-2026 lo es\n     por OTRO motivo \u2014 y el anterior ya no vale, asi que se reescribe entero en vez\n     de dejarlo dando una razon caducada:\n       \u00b7 YA NO es por `firma-submit`. Esa funcion dejo de descargarse este fichero\n         por HTTP (auditoria, hallazgo 01): ahora lleva los cinco dentro, generados\n         por `tools/empaqueta_edge.py`, y dinero.js va PRIMERO en ese paquete.\n       \u00b7 SIGUE vivo mientras haya alguna pagina que cargue este fichero sin cargar\n         `contracts/assets/dinero.js` delante. Hoy no queda ninguna \u2014se le a\u00f1adio a\n         operaciones/, que era la ultima\u2014 pero el respaldo se queda: cuesta ocho\n         lineas y evita que la proxima pantalla que se olvide de dinero.js empiece a\n         devolver 0 en cada importe sin dar ningun error.\n       \u00b7 \u26a0\ufe0f Mientras `firma-submit` no se REDESPLIEGUE, la version que corre en\n         produccion sigue siendo la que se lo descarga con la lista vieja de cuatro\n         rutas. Ese es un estado que se comprueba leyendo la funcion desplegada, no\n         el repo. */\n  if(typeof lwParseImporte === 'function') return lwParseImporte(v) ?? 0;\n  const s = String(v == null ? '' : v).replace(/[^\\d.,-]/g, '');\n  if(!s) return 0;\n  const neg = s.startsWith('-');\n  const cuerpo = s.replace(/-/g, '');\n  const corte = Math.max(cuerpo.lastIndexOf(','), cuerpo.lastIndexOf('.'));\n  let n;\n  if(corte >= 0 && cuerpo.length - corte - 1 <= 2 && cuerpo.length - corte - 1 > 0){\n    n = Number(cuerpo.slice(0, corte).replace(/[.,]/g, '') + '.' + cuerpo.slice(corte + 1));\n  }else{\n    n = Number(cuerpo.replace(/[.,]/g, ''));\n  }\n  if(!isFinite(n)) return 0;\n  return neg ? -n : n;\n}\n\n// Redondeo a los decimales de la moneda, en enteros para no arrastrar\n// el error binario de coma flotante (0.1+0.2 y compa\u00f1\u00eda).\nfunction redondear(n, moneda){\n  const d = DECIMALES[moneda] != null ? DECIMALES[moneda] : 2;\n  const f = Math.pow(10, d);\n  return Math.round((n + Number.EPSILON) * f) / f;\n}\n\n/* Totales de la factura. `lineas` = [{descripcion, importe}], `impuesto` =\n   {etiqueta, pct} y sin pct (o 0) no hay fila de impuesto: el tipo que aplica\n   en Indonesia lo confirma el cliente, aqu\u00ed no se inventa ninguno. */\nfunction calcTotales(lineas, moneda, impuesto){\n  const subtotal = redondear((lineas || []).reduce((a, l) => a + parseImporte(l.importe), 0), moneda);\n  const pct = impuesto ? parseImporte(impuesto.pct) : 0;\n  const imp = pct ? redondear(subtotal * pct / 100, moneda) : 0;\n  return { subtotal, pct, impuesto: imp, total: redondear(subtotal + imp, moneda) };\n}\n\n/* Se DELEGA en contracts/assets/dinero.js desde el 17-ago-2026, igual que\n   `parseImporte`: esta era la \u00fanica de las cuatro formas de imprimir un importe\n   que conoc\u00eda la moneda, as\u00ed que subi\u00f3 a la capa com\u00fan y las otras tres pasaron a\n   llamarla. El respaldo de abajo existe por el mismo motivo que el de\n   `parseImporte` \u2014 ver la nota larga de ah\u00ed arriba, que es la que explica por qu\u00e9\n   no se quita. */\nfunction fmtMoneda(n, moneda){\n  if(typeof lwFormatoImporte === 'function') return lwFormatoImporte(n, moneda);\n  const d = DECIMALES[moneda] != null ? DECIMALES[moneda] : 2;\n  return new Intl.NumberFormat('de-DE', { minimumFractionDigits:d, maximumFractionDigits:d })\n    .format(n || 0) + ' ' + (moneda || '');\n}\n\nif(typeof module !== 'undefined') module.exports = { parseImporte, redondear, calcTotales, fmtMoneda, DECIMALES };\n",
  /* facturas/compradores.js */
  "/* Qui\u00e9n compra en un contrato de Lawang, normalizado a una sola lista.\n   Fuera del HTML para poder pasarle un test de verdad (compradores.test.js).\n   Se carga con <script src> en index.html y con require() en node.\n\n   D\u00f3nde vive cada comprador en `contratos.datos` (verificado 30-jul-2026 sobre\n   los 26 contratos reales):\n   - Adquiriente I  \u2192 `datos.fields.adq1_*`, en TODOS los contratos.\n   - Adquiriente II, III, IV\u2026 \u2192 `datos.compradores[]`, que es como los guarda\n     /contracts (COMPRADORES[0] es el II \u2014 de ah\u00ed el `romano(i+2)` de app.html).\n   - `adq2_*`/`adq3_*` son el formato viejo: solo 2 contratos los llevan, y los\n     nuevos los dejan vac\u00edos. Se leen igual o esos dos pierden compradores.\n\n   Leer solo `adq1..3_*` (lo que hac\u00eda la factura hasta hoy) deja fuera a los\n   adquirientes II+ de CC00007, CC00008 (3 extras), RP00012, RP00016 y RP00018:\n   la factura sal\u00eda a un nombre cuando el contrato va a varios. */\n\nconst trim = v => String(v == null ? '' : v).trim();\n\nfunction compradoresDeContrato(fields, extras){\n  const f = fields || {};\n  const crudos = [\n    { nombre:f.adq1_nombre, pasaporte:f.adq1_pasaporte, domicilio:f.adq1_domicilio, email:f.adq1_email },\n    { nombre:f.adq2_nombre, pasaporte:f.adq2_pasaporte, domicilio:f.adq2_domicilio, email:f.adq2_email },\n    { nombre:f.adq3_nombre, pasaporte:f.adq3_pasaporte, domicilio:f.adq3_domicilio, email:f.adq3_email }\n  ].concat(Array.isArray(extras) ? extras : []);\n\n  const vistos = new Set(), lista = [];\n  crudos.forEach(c => {\n    const nombre = trim(c && c.nombre).replace(/\\s+/g, ' ');\n    if(!nombre) return;\n    const clave = nombre.toLowerCase();\n    if(vistos.has(clave)) return;   // un contrato viejo puede repetir a la misma persona en adq2_* y en compradores[]\n    vistos.add(clave);\n    lista.push({ nombre, pasaporte:trim(c.pasaporte), domicilio:trim(c.domicilio), email:trim(c.email) });\n  });\n  return lista;\n}\n\n// La factura va a nombre de todos los que firman el contrato, no solo del primero.\nfunction nombresFactura(lista){ return (lista || []).map(c => c.nombre).join(' \u00b7 '); }\n\n/* Documentos de identidad. Con un comprador va el n\u00famero suelto; con varios se\n   etiqueta con el nombre, porque si no no se sabe de qui\u00e9n es cada pasaporte.\n   A quien no tenga pasaporte guardado no se le inventa nada: no aparece. */\nfunction documentosFactura(lista){\n  const con = (lista || []).filter(c => c.pasaporte);\n  if(!con.length) return '';\n  if((lista || []).length === 1) return con[0].pasaporte;\n  return con.map(c => c.nombre + ': ' + c.pasaporte).join(' \u00b7 ');\n}\n\n// Primer valor no vac\u00edo de un campo (domicilio/email de notificaciones de la factura).\nfunction primerDato(lista, campo){\n  const c = (lista || []).find(x => x[campo]);\n  return c ? c[campo] : '';\n}\n\nif(typeof module !== 'undefined') module.exports = { compradoresDeContrato, nombresFactura, documentosFactura, primerDato };\n",
  /* facturas/documento.js */
  "/* ============================================================================\n   El DOCUMENTO de la factura \u2014 FUENTE \u00daNICA de su maquetaci\u00f3n\n   ----------------------------------------------------------------------------\n   Devuelve el HTML del papel (cabecera, cliente, conceptos, totales, banco,\n   notas, pie). Lo usan DOS sitios y por eso vive aqu\u00ed:\n\n     \u00b7 `facturas/index.html`  \u2014 la vista previa viva y el PDF que imprime el\n       navegador cuando alguien emite a mano.\n     \u00b7 `contracts/edge/firma-submit` \u2014 la factura del primer hito que sale sola\n       al cerrarse la firma de un contrato. La Edge Function se BAJA este mismo\n       fichero y lo ejecuta, as\u00ed que no hay una segunda versi\u00f3n del documento\n       que se quede vieja: si aqu\u00ed cambia una fila, cambia en los dos.\n\n   Los estilos van en `documento.css`, tambi\u00e9n compartido. Aqu\u00ed solo el marcado.\n\n   Sin m\u00f3dulos ES a prop\u00f3sito (mismo criterio que entities.js y totales.js):\n   index.html es HTML plano con <script> cl\u00e1sico, y la Edge Function eval\u00faa el\n   texto de este fichero. El `module.exports` del final es para el test en node.\n\n   Depende de globales que ponen los otros ficheros compartidos:\n     SOCIEDADES, CUENTAS_BANCARIAS (entities.js) \u00b7 calcTotales, fmtMoneda,\n     parseImporte (totales.js).\n   ========================================================================== */\n\n/* R\u00f3tulos del tipo de documento. Cada uno lleva su propia serie en base de\n   datos (INV / PRO / REC): una proforma no es documento fiscal y no puede\n   consumir n\u00fameros de la serie de facturas. */\nvar TIPOS_DOC = {\n  factura:  { es:'Factura',          en:'Invoice',          serie:'INV' },\n  proforma: { es:'Factura proforma', en:'Proforma invoice', serie:'PRO' },\n  recibi:   { es:'Recib\u00ed',           en:'Receipt',          serie:'REC' },\n};\n\nfunction escDoc(s){\n  return String(s == null ? '' : s).replace(/[&<>\"]/g,\n    c => ({ '&':'&amp;', '<':'&lt;', '>':'&gt;', '\"':'&quot;' }[c]));\n}\n\n/* Datos bancarios en DOS columnas: en una sola, seis filas de etiqueta/valor\n   com\u00edan 44mm de folio y empujaban la factura a la segunda p\u00e1gina con solo dos\n   conceptos. Los cuatro datos cortos van en dos columnas y los dos largos\n   (direcci\u00f3n del banco y nota) a ancho completo, que en media columna se\n   part\u00edan en tres l\u00edneas y no ahorraban nada.\n\n   `cuenta === 'otros'` = cuenta escrita a mano en el formulario, para cobrar por\n   una que no est\u00e1 dada de alta en entities.js sin frenar la emisi\u00f3n. Se arma un\n   objeto con la misma forma para que el resto no tenga que distinguir. */\nfunction bancoDocHTML(d){\n  var c = d.cuenta === 'otros'\n    ? { titular:d.banco_titular, banco:d.banco_nombre, cuenta:d.banco_cuenta,\n        codigo:d.banco_codigo, direccion:d.banco_direccion, extra:d.banco_extra }\n    : (typeof CUENTAS_BANCARIAS !== 'undefined' ? CUENTAS_BANCARIAS[d.cuenta] : null);\n  var txt = v => (v && typeof v === 'object') ? (v.es || '') : (v || '');\n  // Sin ning\u00fan dato relleno no se imprime el bloque: una cabecera \"Datos\n  // bancarios\" con seis guiones es peor que no ponerla.\n  if(!c || !Object.keys(c).some(k => txt(c[k]))) return '';\n  var dato = (l, v, ancho) => txt(v)\n    ? '<div class=\"' + (ancho ? 'ancho' : '') + '\"><span>' + l + '</span>' + escDoc(txt(v)) + '</div>' : '';\n  return '<h3>Datos bancarios \u00b7 Bank details</h3>' +\n    '<div class=\"banco\">' +\n      dato('Titular \u00b7 Holder', c.titular) +\n      dato('Banco \u00b7 Bank', c.banco) +\n      dato('Cuenta \u00b7 Account', c.cuenta) +\n      dato('Swift / Routing', c.codigo) +\n      dato('Direcci\u00f3n \u00b7 Address', c.direccion, true) +\n      dato('Nota \u00b7 Note', c.extra, true) +\n    '</div>';\n}\n\n/* Variables de tinta del documento. Todo lo coloreado (filete de cabecera,\n   titulares, r\u00f3tulos, cabecera de tabla y l\u00ednea del total) sale de aqu\u00ed, as\u00ed que\n   cambiarlas repinta el documento entero. Cadena vac\u00eda = se borra el override y\n   vuelve el verde/lagoon de brand.css.\n   `--folio` es el color del PAPEL y va en `.sheet`, que est\u00e1 FUERA de `.doc`:\n   ponerlo en `.doc` pintar\u00eda solo bajo el contenido y dejar\u00eda blancos los\n   m\u00e1rgenes. */\nfunction documentoVars(soc){\n  soc = soc || {};\n  return {\n    hoja: { '--folio': soc.folio || '' },\n    doc: {\n      '--brand-primary': (soc.tinta && soc.tinta.primary) || '',\n      '--brand-deep':    (soc.tinta && soc.tinta.deep)    || '',\n      '--logo-alto':     soc.logoAlto   || '',\n      '--logo2-ancho':   soc.logo2Ancho || '',\n    },\n  };\n}\n\n/* `d` = los campos del formulario (collect()). `opts.numero` = el n\u00famero ya\n   emitido; sin \u00e9l la l\u00ednea no se pinta, porque un documento sin n\u00famero es uno\n   que todav\u00eda no se ha emitido. `opts.base` antepone el host a las rutas de los\n   logos: en pantalla sobran, pero el renderizador de PDF carga el HTML desde\n   otro sitio y una ruta relativa no resolver\u00eda. */\nfunction documentoHTML(d, opts){\n  opts = opts || {};\n  var base = opts.base || '';\n  var numero = opts.numero || '';\n  var soc = (typeof SOCIEDADES !== 'undefined' && SOCIEDADES[d.sociedad]) ||\n            (typeof SOCIEDADES !== 'undefined' && SOCIEDADES.tepi_sungai) || {};\n  var t = calcTotales(d.lineas, d.moneda, { pct: d.imp_pct });\n  var tipo = TIPOS_DOC[d.tipo] || TIPOS_DOC.factura;\n  var linea = v => v ? escDoc(v) : '<span class=\"vacio\">\u2014</span>';\n  var fecha = f => f\n    ? new Date(f + 'T00:00:00').toLocaleDateString('es-ES', { day:'2-digit', month:'long', year:'numeric' })\n    : '';\n  var url = u => (u && base && u.charAt(0) === '/') ? base.replace(/\\/$/, '') + u : u;\n\n  var filas = d.lineas.map(l => (l.descripcion || l.importe)\n      ? '<tr><td>' + escDoc(l.descripcion) + '</td><td class=\"imp\">' +\n        fmtMoneda(parseImporte(l.importe), d.moneda) + '</td></tr>' : ''\n    ).join('') || '<tr><td class=\"vacio\">Sin conceptos</td><td class=\"imp vacio\">\u2014</td></tr>';\n\n  /* Sin `logo` en la sociedad NO se pinta ninguno, y a prop\u00f3sito: el fallback al\n     de Lawang que hab\u00eda aqu\u00ed convirti\u00f3 un entities.js cacheado en una factura de\n     PT SAN DAL WOODS con la marca de otra empresa, sin que se notara. Un\n     documento sin logo salta a la vista; uno con el logo equivocado, no. */\n  return '' +\n  '<div class=\"head\">' +\n    '<div class=\"emisor-bloque' + (soc.emisorDebajo ? ' apilado' : '') + '\">' +\n      '<div class=\"marcas\">' +\n        (soc.logo  ? '<img src=\"' + escDoc(url(soc.logo)) + '\" alt=\"\">' : '') +\n        (soc.logo2 ? '<img class=\"logo2\" src=\"' + escDoc(url(soc.logo2)) + '\" alt=\"\">' : '') +\n      '</div>' +\n      '<div class=\"emisor\">' +\n        '<b>' + escDoc(soc.razon) + '</b>' +\n        (soc.marca ? '<span class=\"marca\">' + escDoc(soc.marca) + '</span>' : '') +\n        '<div>' + escDoc(soc.domicilio) + '</div>' +\n        '<div>' + escDoc(soc.npwpLabel || 'NPWP') + ' ' + escDoc(soc.npwp) + '</div>' +\n      '</div>' +\n    '</div>' +\n    '<div class=\"titulo\">' +\n      '<h2>' + escDoc(tipo.es) + '</h2>' +\n      '<div class=\"titulo-en\">' + escDoc(tipo.en) + '</div>' +\n      (numero ? '<div class=\"num\">' + escDoc(numero) + '</div>' : '') +\n      '<div class=\"meta\">' +\n        (d.fecha_emision ? 'Fecha \u00b7 Date: ' + escDoc(fecha(d.fecha_emision)) + '<br>' : '') +\n        (d.fecha_vencimiento ? 'Vencimiento \u00b7 Due: ' + escDoc(fecha(d.fecha_vencimiento)) + '<br>' : '') +\n        (d.contrato_numero ? 'Contrato \u00b7 Contract: ' + escDoc(d.contrato_numero) : '') +\n      '</div>' +\n    '</div>' +\n  '</div>' +\n\n  '<h3>Facturar a \u00b7 Bill to</h3>' +\n  '<div class=\"cliente\">' +\n    '<b>' + linea(d.cliente_nombre) + '</b><br>' +\n    (d.cliente_documento ? escDoc(d.cliente_documento) + '<br>' : '') +\n    (d.cliente_domicilio ? escDoc(d.cliente_domicilio).replace(/\\n/g, '<br>') + '<br>' : '') +\n    (d.cliente_email ? escDoc(d.cliente_email) : '') +\n    (d.proyecto_nombre ? '<div style=\"margin-top:2mm\">Proyecto \u00b7 Project: <b>' + escDoc(d.proyecto_nombre) + '</b></div>' : '') +\n  '</div>' +\n\n  '<h3>Conceptos \u00b7 Items</h3>' +\n  '<table><thead><tr><th>Descripci\u00f3n \u00b7 Description</th><th class=\"imp\">Importe \u00b7 Amount</th></tr></thead>' +\n    '<tbody>' + filas + '</tbody></table>' +\n\n  '<table class=\"totales\"><tbody>' +\n    '<tr><td>Subtotal</td><td class=\"imp\">' + fmtMoneda(t.subtotal, d.moneda) + '</td></tr>' +\n    (t.pct ? '<tr><td>' + escDoc(d.imp_etiqueta || 'Impuesto \u00b7 Tax') + ' (' + escDoc(String(t.pct)) + '%)</td>' +\n             '<td class=\"imp\">' + fmtMoneda(t.impuesto, d.moneda) + '</td></tr>' : '') +\n    '<tr class=\"total\"><td>Total</td><td class=\"imp\">' + fmtMoneda(t.total, d.moneda) + '</td></tr>' +\n  '</tbody></table>' +\n\n  bancoDocHTML(d) +\n  (d.notas ? '<h3>Notas \u00b7 Notes</h3><div class=\"notas\">' + escDoc(d.notas) + '</div>' : '') +\n\n  '<div class=\"pie\">' + escDoc(soc.razon) + (soc.marca ? ' \u00b7 ' + escDoc(soc.marca) : '') +\n    ' \u00b7 ' + escDoc(soc.npwpLabel || 'NPWP') + ' ' + escDoc(soc.npwp) + ' \u00b7 ' + escDoc(soc.domicilio) + '</div>';\n}\n\n/* Documento COMPLETO y aut\u00f3nomo, para mandarlo al renderizador de PDF (Chromium\n   real en Railway) desde fuera del navegador. `base` tiene que ser absoluto: el\n   servicio carga el HTML desde otro sitio y con rutas relativas ni la hoja de\n   estilos ni los logos resolver\u00edan. */\nfunction documentoPagina(d, opts){\n  opts = opts || {};\n  var base = (opts.base || '').replace(/\\/$/, '');\n  var v = documentoVars((typeof SOCIEDADES !== 'undefined' && SOCIEDADES[d.sociedad]) || {});\n  var estilo = k => Object.keys(v[k]).filter(p => v[k][p]).map(p => p + ':' + v[k][p]).join(';');\n  return '<!DOCTYPE html><html lang=\"es\"><head><meta charset=\"UTF-8\">' +\n    '<base href=\"' + base + '/\">' +\n    '<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">' +\n    '<link href=\"https://fonts.googleapis.com/css2?family=Jost:wght@300;400;500;600&family=Cormorant+Garamond:wght@400;500;600&display=swap\" rel=\"stylesheet\">' +\n    '<link rel=\"stylesheet\" href=\"' + base + '/contracts/assets/brand.css\">' +\n    '<link rel=\"stylesheet\" href=\"' + base + '/facturas/documento.css\">' +\n    /* \ud83d\udd34 6-ago-2026 \u2014 ESTE BLOQUE ES LA HOJA COMPLETA, no un remate.\n       El documento que se manda por correo sal\u00eda \u00abcon un formateo que no tiene\n       nada que ver\u00bb con la vista previa de la herramienta (reportado por el\n       owner), y la causa era que aqu\u00ed faltaban DOS declaraciones que en\n       /facturas/ las pone el <style> de la propia p\u00e1gina:\n         \u00b7 `font-family` \u2014 `brand.css` define el TOKEN `--font-body` pero no lo\n           aplica a `body`, y `documento.css` solo pone tipograf\u00eda en el titular.\n           Sin esto el documento entero sal\u00eda en el serif por defecto del\n           navegador (Times), no en Jost.\n         \u00b7 `background` en `.sheet` \u2014 `documentoVars` calcula bien el folio de\n           cada sociedad y lo deja en `--folio`, pero NADIE lo consum\u00eda aqu\u00ed: el\n           papel sal\u00eda blanco. O sea que la identidad por sociedad (30-jul) se\n           perd\u00eda en TODA factura enviada por correo y en las autom\u00e1ticas de la\n           firma, que son justo las que ve el comprador.\n       Los valores llevan fallback porque esta p\u00e1gina se renderiza fuera del\n       navegador y `brand.css` podr\u00eda no llegar; un documento en Jost sobre papel\n       blanco es aceptable, uno en Times no.\n       Lo que NO se copia de la p\u00e1gina, y es correcto: `zoom` y `box-shadow`, que\n       son de pantalla (el zoom adem\u00e1s no se aplica dentro de @media print). */\n    '<style>@page{size:A4;margin:0}html,body{margin:0}' +\n    'body{font-family:var(--font-body,\\'Jost\\',sans-serif);color:var(--ink,#2E3437)}' +\n    '.sheet{width:210mm;min-height:297mm;padding:15mm 16mm;box-sizing:border-box;' +\n    'background:var(--folio,#fff)}</style>' +\n    '</head><body>' +\n    '<div class=\"sheet\" style=\"' + estilo('hoja') + '\">' +\n      '<div class=\"doc\" style=\"' + estilo('doc') + '\">' + documentoHTML(d, opts) + '</div>' +\n    '</div></body></html>';\n}\n\nif(typeof module !== 'undefined')\n  module.exports = { TIPOS_DOC, escDoc, bancoDocHTML, documentoVars, documentoHTML, documentoPagina };\n",
];

/* Lo que hay que sacar a la caja tras evaluarlas. Generado de la misma lista,
   para que no pueda quedarse corto respecto a lo que definen los ficheros.
   Va con un elemento por linea y cerrando en `\n];`, igual que FUENTES: asi
   `compartidos.test.js` lee los dos arrays con el mismo corte. Escrito en una
   sola linea, ese test no encontraba este y fallaba diciendo que el paquete
   tenia otra forma — cierto, pero por el sitio equivocado. */
export const EXPORTA: string[] = [
  "SOCIEDADES",
  "CUENTAS_BANCARIAS",
  "calcTotales",
  "fmtMoneda",
  "parseImporte",
  "compradoresDeContrato",
  "nombresFactura",
  "documentosFactura",
  "primerDato",
  "documentoPagina",
  "TIPOS_DOC",
];
